<?php require_once __DIR__ . '/auth.php'; require_login('student');$user=current_user();$uid=$user['id'];$skills=many('SELECT sk.name,ss.score,ss.level FROM student_skills ss JOIN skills sk ON sk.id=ss.skill_id WHERE ss.user_id=? ORDER BY ss.score DESC','i',[$uid]);$stats=one('SELECT COALESCE(SUM(questions_count),0) solved,COALESCE(ROUND(AVG(accuracy)),0) accuracy FROM quiz_attempts WHERE user_id=?','i',[$uid]);$pageTitle='My resume';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">Auto-generated profile</div><h1>Your resume.</h1><p>Every verified assessment keeps this profile current.</p></div><button class="button button-dark" onclick="window.print()">Print / save PDF <span>↓</span></button></div><article class="resume"><div class="resume-top"><div><h1><?=e($user['name'])?></h1><p><?=e($user['course'])?> · <?=e($user['university'])?></p><small><?=e($user['email'])?> · <?=e($user['phone']??'')?></small></div><div style="text-align:right"><span class="pill lime">SkillRank verified</span><p><?=e($user['semester'])?></p></div></div><div class="resume-section"><h3>Profile</h3><p>Curious, consistent computer science student building practical depth through verified academic and technical assessments.</p></div><div class="resume-section"><h3>Technical skills</h3><div class="tag-list"><?php foreach($skills as $skill):?><span class="tag"><?=e($skill['name'])?> · <?=e($skill['level'])?></span><?php endforeach;?></div></div><div class="resume-section"><h3>Verified outcomes</h3><div class="stat-grid"><div><small>Questions solved</small><strong><?=number_format($stats['solved'])?></strong></div><div><small>Accuracy</small><strong><?=$stats['accuracy']?>%</strong></div><div><small>Rank</small><strong>#07</strong></div></div></div><div class="resume-section"><h3>Achievements</h3><p>Consistency Champion · PHP Problem Solver · Top 10 Momentum</p></div></article><?php include 'includes/footer.php';?>